def max_product(num_str: str, N: int, K: int) -> int:
    if not num_str or K == 0:
        return 0

    # Convert string to list for easy manipulation
    nums = list(map(int, num_str))

    # Initialize the answer variable to the first number
    result = nums[0]

    # Iterate through the array, inserting multiplication signs
    for i in range(1, N):
        current_num = nums[i]
        # Check if we can insert multiplication signs before the current number
        if i + K - 1 < N:
            if current_num == 0:
                # If current number is zero, skip inserting a multiplication sign
                result = max(result * nums[i + K - 1], 0)
            else:
                result = max(result * current_num * nums[i + K - 1], result)
    return result

