def max_happiness(n, m, items):
    rows = m + 1
    cols = n + 1

    # Create a 2D array to store the values for each item and budget
    dp = [[0] * cols for _ in range(rows)]

    # Fill the dp array using dynamic programming
    for i in range(1, rows):
        for j in range(1, cols):
            price, importance = items[i-1]
            if price <= j:
                dp[i][j] = max(importance + dp[i-1][j-price], dp[i-1][j])
            else:
                dp[i][j] = dp[i-1][j]

    # The top-right cell in dp array contains the maximum happiness
    return dp[m][n]

def max_energy(beads: List[int]) -> int:
    n = len(beads)
    dp = [[0] * n for _ in range(n)]

    # Base case: single bead
    for i in range(n):
        dp[i][i] = beads[i] * beads[(i + 1) % n]

    # Fill the dp table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = max(beads[i] * beads[(i + 1) % n] * dp[i + 1][j], beads[j] * beads[(j - 1) % n] * dp[i][j - 1])

    return dp[0][n - 1]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    result = ""
    zeros = 0
    for i, coeff in enumerate(coeffs):
        if coeff != 0:
            if zeros > 0:
                coeff *= -1
            term = ""
            if coeff < 0:
                term += "-"
            if i == 0:
                term += str(abs(coeff))
            elif i == n:
                term += f"x^0"
            else:
                term += f"x^{n-i}"
            if abs(coeff) != 1 or term == "1":
                result += term
            zeros = 0
        else:
            zeros += 1
    if result == "":
        return "0"
    return result

